package cn.finance.review;
import java.util.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.*;
import org.springframework.security.core.Authentication;
import static cn.finance.review.Db.*;
import static cn.finance.review.ApiError.require;
@Service
public class QueryService {
 final Db db;final Access access;final PublicationService publications;
 public QueryService(Db db,Access access,PublicationService publications){this.db=db;this.access=access;this.publications=publications;}
 @Transactional(isolation=Isolation.REPEATABLE_READ)
 public Map<String,Object> snapshot(Authentication a){List<String> scope=access.scope(a);require(!scope.isEmpty(),403,"NO_DATA_SCOPE","当前身份没有财经数据访问范围");String id=id();db.insert("snapshot",map("id",id,"scopeHash",access.scopeHash(a),"createdAt",now()));var entries=db.rows("SELECT product_id,release_id FROM product_publication WHERE product_id IN (:ids)",Map.of("ids",scope));for(var e:entries)e.put("snapshotId",id);db.insertBatch("snapshot_entry",entries);return map("id",id,"createdAt",now());}
 public Map<String,Object> snapshotMeta(Authentication a,String id){require(id!=null&&!id.isBlank(),422,"SNAPSHOT_REQUIRED","查询必须指定快照");var s=db.one("SELECT * FROM snapshot WHERE id=:id",Map.of("id",id));require(access.scopeHash(a).equals(str(s,"scopeHash")),403,"SCOPE_CHANGED","数据范围已变化，请刷新快照");return s;}
 public List<String> datasets(Authentication a,String snapshot,String product,String chain){snapshotMeta(a,snapshot);if(product!=null&&!product.isBlank()&&!product.equals("all"))access.product(a,product,"read");String column=chain.equals("user")?"user_dataset_id":"matrix_dataset_id";String where=product!=null&&!product.isBlank()&&!product.equals("all")?" AND e.product_id=:p":"";Map<String,Object> p=map("s",snapshot,"p",product);return db.rows("SELECT r."+column+" AS id FROM snapshot_entry e JOIN product_release r ON e.release_id=r.id WHERE e.snapshot_id=:s"+where+" AND r."+column+" IS NOT NULL",p).stream().map(r->str(r,"id")).toList();}
 public Map<String,Object> riskStats(List<String> ids){Map<String,Object> m=map("total",0L,"high",0L,"medium",0L,"low",0L,"manual",0L,"recheck",0L,"falsePositive",0L,"originalHits",0L,"userRiskCount",0L,"matrixRiskCount",0L);if(ids.isEmpty())return m;return db.one("SELECT COUNT(*) AS original_hits, COALESCE(SUM(CASE WHEN workflow<>'已确认误报' THEN 1 ELSE 0 END),0) AS total, COALESCE(SUM(CASE WHEN workflow='已确认误报' THEN 1 ELSE 0 END),0) AS false_positive, COALESCE(SUM(CASE WHEN workflow<>'已确认误报' AND risk='高' THEN 1 ELSE 0 END),0) AS high, COALESCE(SUM(CASE WHEN workflow<>'已确认误报' AND risk='中' THEN 1 ELSE 0 END),0) AS medium, COALESCE(SUM(CASE WHEN workflow<>'已确认误报' AND risk='低' THEN 1 ELSE 0 END),0) AS low, COALESCE(SUM(CASE WHEN workflow='待人工确认' THEN 1 ELSE 0 END),0) AS manual, COALESCE(SUM(CASE WHEN workflow='待复核' THEN 1 ELSE 0 END),0) AS recheck, COALESCE(SUM(CASE WHEN workflow<>'已确认误报' AND chain='user' THEN 1 ELSE 0 END),0) AS user_risk_count, COALESCE(SUM(CASE WHEN workflow<>'已确认误报' AND chain='matrix' THEN 1 ELSE 0 END),0) AS matrix_risk_count FROM risk_finding WHERE dataset_id IN (:ids)",Map.of("ids",ids));}
 public Map<String,Object> people(List<String> ids){if(ids.isEmpty())return map("users",null,"it",null,"business",null,"external",null,"other",null);String category="CASE WHEN person_kind IN ('IT人员','云山用户','IT') THEN 'it' WHEN person_kind IN ('业务人员','业务') AND employment_class='雇员' THEN 'business' WHEN person_kind IN ('业务人员','业务') AND employment_class='非雇员' THEN 'external' ELSE 'other' END";
  String sub="SELECT user_key AS emp,CASE WHEN COUNT(DISTINCT "+category+")=1 THEN MIN("+category+") ELSE 'other' END AS category FROM source_auth WHERE dataset_id IN (:ids) GROUP BY user_key";
  return db.one("SELECT COUNT(*) AS users,COALESCE(SUM(CASE WHEN category='it' THEN 1 ELSE 0 END),0) AS it,COALESCE(SUM(CASE WHEN category='business' THEN 1 ELSE 0 END),0) AS business,COALESCE(SUM(CASE WHEN category='external' THEN 1 ELSE 0 END),0) AS external,COALESCE(SUM(CASE WHEN category='other' THEN 1 ELSE 0 END),0) AS other FROM ("+sub+") users_grouped",Map.of("ids",ids));
 }
 public Map<String,Object> dashboard(Authentication a,String snapshot){var meta=snapshotMeta(a,snapshot);var products=db.rows("SELECT p.*,e.release_id,r.user_dataset_id,r.matrix_dataset_id,r.published_at,r.release_number FROM product p JOIN snapshot_entry e ON p.id=e.product_id LEFT JOIN product_release r ON r.id=e.release_id WHERE e.snapshot_id=:s ORDER BY p.id",Map.of("s",snapshot));List<String> allRisk=new ArrayList<>(),allAuth=new ArrayList<>();int covered=0,rawFull=0;
  for(var p:products){var r=p;List<String> ids=new ArrayList<>();String user=str(r,"userDatasetId"),matrix=str(r,"matrixDatasetId");if(!user.isBlank())ids.add(user);if(!matrix.isBlank())ids.add(matrix);allRisk.addAll(ids);var m=riskStats(ids);p.put("metrics",m);p.put("userRiskCount",m.get("userRiskCount"));p.put("matrixRiskCount",m.get("matrixRiskCount"));p.put("updatedAt",r.get("publishedAt"));p.put("releaseNumber",r.getOrDefault("releaseNumber",0));p.put("summary",summary(user,matrix));
   Map<String,Object> ud=user.isBlank()?map("rawCoverage","UNKNOWN","riskCoverage","UNKNOWN","rawAsOf","","riskAsOf",""):db.one("SELECT * FROM review_dataset WHERE id=:id",Map.of("id",user));Map<String,Object> md=matrix.isBlank()?map("rawCoverage","UNKNOWN","riskCoverage","UNKNOWN","rawAsOf","","riskAsOf",""):db.one("SELECT * FROM review_dataset WHERE id=:id",Map.of("id",matrix));p.put("userCoverage",ud);p.put("matrixCoverage",md);boolean hasAuth=!str(ud,"rawCoverage").equals("UNKNOWN");if(hasAuth){allAuth.add(user);p.put("authorizations",db.count("SELECT COUNT(*) FROM source_auth WHERE dataset_id=:id",Map.of("id",user)));p.put("userCount",people(List.of(user)).get("users"));}else {p.put("authorizations",null);p.put("userCount",null);}if(!ids.isEmpty())covered++;if(str(ud,"rawCoverage").equals("FULL"))rawFull++;
  }
  var overall=riskStats(allRisk);overall.putAll(people(allAuth));overall.put("authorizations",allAuth.isEmpty()?null:db.count("SELECT COUNT(*) FROM source_auth WHERE dataset_id IN (:ids)",Map.of("ids",allAuth)));overall.put("affected",products.stream().filter(p->((Number)((Map<?,?>)p.get("metrics")).get("total")).longValue()>0).count());overall.put("coveredProducts",covered);overall.put("rawFullProducts",rawFull);overall.put("productCount",products.size());overall.put("rawCoverage",rawFull==products.size()?"FULL":allAuth.isEmpty()?"UNKNOWN":"PARTIAL");return map("snapshotId",snapshot,"createdAt",meta.get("createdAt"),"products",products,"overall",overall,"ruleDistribution",ruleDistribution(allRisk));
 }
 public List<Map<String,Object>> ruleDistribution(List<String> datasets){Map<String,Long> counts=new HashMap<>();if(!datasets.isEmpty())for(var r:db.rows("SELECT CASE WHEN chain='matrix' THEN '8' ELSE rule_code END AS rule_id,COUNT(*) AS count FROM risk_finding WHERE dataset_id IN (:ids) AND workflow<>'已确认误报' GROUP BY CASE WHEN chain='matrix' THEN '8' ELSE rule_code END",map("ids",datasets)))counts.put(str(r,"ruleId"),((Number)r.get("count")).longValue());long total=counts.values().stream().mapToLong(Long::longValue).sum();List<Map<String,Object>> rows=new ArrayList<>();for(int i=1;i<=8;i++){long count=counts.getOrDefault(String.valueOf(i),0L);rows.add(map("id",String.valueOf(i),"name",Fields.RULE_NAMES[i-1],"kind",i==8?"matrix":"user","count",count,"share",total==0?0d:count/(double)total));}return rows;}
 List<Map<String,Object>> summary(String user,String matrix){
  List<String> ids=new ArrayList<>();if(!user.isBlank())ids.add(user);if(!matrix.isBlank())ids.add(matrix);Map<String,Long> counts=new HashMap<>();
  if(!ids.isEmpty())for(var r:db.rows("SELECT dataset_id,rule_code,COUNT(*) AS count FROM risk_finding WHERE dataset_id IN (:ids) AND workflow<>'已确认误报' GROUP BY dataset_id,rule_code",map("ids",ids)))counts.merge(str(r,"datasetId")+"|"+(str(r,"ruleCode").startsWith("8")?"8":str(r,"ruleCode")),((Number)r.get("count")).longValue(),Long::sum);
  List<Map<String,Object>> out=new ArrayList<>();for(int i=1;i<=8;i++){String ds=i==8?matrix:user;long count=counts.getOrDefault(ds+"|"+i,0L);String result=ds.isBlank()?"未提供":count==0?"未检出记录":i==7?"需人工确认":i==3||i==4?"存在风险":"风险";out.add(map("id",String.valueOf(i),"name",Fields.RULE_NAMES[i-1],"kind",i==8?"matrix":"user","count",count,"result",result,"risk",i==6?"中":i==7?"低":"高"));}return out;
 }
 public record Built(String from,String where,Map<String,Object> parameters,String order){}
 public Built build(Authentication a,Map<String,Object> input,boolean source){String chain=str(input,"kind");require(List.of("user","matrix").contains(chain),422,"CHAIN","链路无效");var ids=datasets(a,str(input,"snapshotId"),str(input,"productId"),chain);Map<String,Object> params=map("ids",ids.isEmpty()?List.of("__no_dataset__"):ids);Map<String,String> fields=new LinkedHashMap<>();List<String> columns=source?Fields.sourceColumns(chain):new ArrayList<>(Fields.COMMON);if(!source)columns.addAll(Fields.detailColumns(chain));for(String key:columns)fields.put(key,(source?"f.":Fields.COMMON.contains(key)?"f.":"d.")+Db.snake(key));if(!source){fields.put("checkItem","f.rule_code");fields.put("subcheck","f.rule_code");}
  String from=source?" FROM "+Fields.sourceTable(chain)+" f":" FROM risk_finding f JOIN "+Fields.detailTable(chain)+" d ON f.id=d.finding_id";from+=" JOIN review_dataset ds_meta ON f.dataset_id=ds_meta.id";StringBuilder w=new StringBuilder(" WHERE f.dataset_id IN (:ids)");if(!source&&!Boolean.TRUE.equals(input.get("includeFalsePositive")))w.append(" AND f.workflow<>'已确认误报'");
  String q=str(input,"q").trim();require(q.length()<=500,422,"QUERY_LENGTH","查询关键词过长");if(!q.isBlank()){List<String> parts=new ArrayList<>();for(String col:new LinkedHashSet<>(fields.values()))parts.add("LOWER(CAST("+col+" AS VARCHAR)) LIKE :q ESCAPE '!'");w.append(" AND (").append(String.join(" OR ",parts)).append(")");params.put("q","%"+escape(q.toLowerCase(Locale.ROOT))+"%");}
  Object filters=input.get("filters");if(filters instanceof List<?> list){require(list.size()<=60,422,"FILTER_LIMIT","筛选条件过多");int n=0;for(Object obj:list){require(obj instanceof Map<?,?>,422,"FILTER","筛选格式无效");Map<?,?> filter=(Map<?,?>)obj;String field=String.valueOf(filter.get("field")),op=String.valueOf(filter.get("op"));String col=fields.get(field);require(col!=null,422,"FILTER_FIELD","筛选字段不受支持");String key="v"+n++;Object value=filter.get("value");if(op.equals("contains")){w.append(" AND LOWER(CAST(").append(col).append(" AS VARCHAR)) LIKE :").append(key).append(" ESCAPE '!'");params.put(key,"%"+escape(String.valueOf(value).toLowerCase(Locale.ROOT))+"%");}else if(List.of("eq","gte","lte").contains(op)){w.append(" AND ").append(col).append(op.equals("eq")?" = :":op.equals("gte")?" >= :":" <= :").append(key);params.put(key,field.equals("confidence")?parseNumber(value):String.valueOf(value));}else if(op.equals("in")&&value instanceof List<?> vals){require(!vals.isEmpty()&&vals.size()<=100,422,"FILTER_VALUES","集合条件应为1至100个值");w.append(" AND ").append(col).append(" IN (:").append(key).append(")");params.put(key,vals);}else throw new ApiError(422,"FILTER_OP","筛选操作不受支持");}}
  String sort=str(input,"sortField");String order="f.id";if(!sort.isBlank()){require(fields.containsKey(sort),422,"SORT_FIELD","排序字段不受支持");order=fields.get(sort)+(str(input,"sortDirection").equals("desc")?" DESC":" ASC")+", f.id";}return new Built(from,w.toString(),params,order);
 }
 static double parseNumber(Object value){try{double n=Double.parseDouble(String.valueOf(value));if(!Double.isFinite(n))throw new Exception();return n;}catch(Exception e){throw new ApiError(422,"FILTER_VALUE","数值条件无效");}}
 static String escape(String x){return x.replace("!","!!").replace("%","!%").replace("_","!_");}
 public Map<String,Object> query(Authentication a,Map<String,Object> input,boolean source){Built b=build(a,input,source);int page=Math.max(1,input.get("page") instanceof Number n?n.intValue():1),size=input.get("pageSize") instanceof Number n?n.intValue():20;require(page<=100000&&size>=1&&size<=100,422,"PAGINATION","每页支持1至100条");long total=db.count("SELECT COUNT(*)"+b.from+b.where,b.parameters);Map<String,Object> p=new LinkedHashMap<>(b.parameters);p.put("limit",size);p.put("offset",(page-1)*size);String projection=(source?"f.*":"f.*,d.*")+",ds_meta.product_id AS product_id";var rows=db.rows("SELECT "+projection+b.from+b.where+" ORDER BY "+b.order+" LIMIT :limit OFFSET :offset",p);for(var r:rows){r.put("recordId",r.get("id"));r.put("kind",input.get("kind"));if(!source){r.put("checkItem",r.get("ruleCode"));r.put("subcheck",r.get("ruleCode"));}}
  var u=datasets(a,str(input,"snapshotId"),str(input,"productId"),"user");var m=datasets(a,str(input,"snapshotId"),str(input,"productId"),"matrix");var ids=new ArrayList<String>(u);ids.addAll(m);var counts=riskStats(ids);if(source){counts.put("userRiskCount",u.isEmpty()?0L:db.count("SELECT COUNT(*) FROM source_auth WHERE dataset_id IN (:ids)",Map.of("ids",u)));counts.put("matrixRiskCount",m.isEmpty()?0L:db.count("SELECT COUNT(*) FROM source_point WHERE dataset_id IN (:ids)",Map.of("ids",m)));}return map("rows",rows,"total",total,"page",page,"pageSize",size,"snapshotId",input.get("snapshotId"),"counts",map("user",counts.get("userRiskCount"),"matrix",counts.get("matrixRiskCount")));
 }
 public Map<String,Object> trace(Authentication a,String id,String snapshot,boolean source,String kind){snapshotMeta(a,snapshot);if(source){require(List.of("user","matrix").contains(kind),422,"CHAIN","链路无效");var raw=db.one("SELECT * FROM "+Fields.sourceTable(kind)+" WHERE id=:id",Map.of("id",id));require(datasets(a,snapshot,"all",kind).contains(str(raw,"datasetId")),404,"NOT_FOUND","记录不属于所选快照");var ds=db.one("SELECT product_id FROM review_dataset WHERE id=:id",Map.of("id",raw.get("datasetId")));return map("kind",kind,"sourceOnly",true,"recordId",raw.get("id"),"productId",ds.get("productId"),"raw",raw,"auditedRaw",null,"changes",List.of());}
  var f=db.one("SELECT * FROM risk_finding WHERE id=:id",Map.of("id",id));String chain=str(f,"chain");require(datasets(a,snapshot,"all",chain).contains(str(f,"datasetId")),404,"NOT_FOUND","记录不属于所选快照");var detail=db.one("SELECT * FROM "+Fields.detailTable(chain)+" WHERE finding_id=:id",Map.of("id",id));f.putAll(detail);f.put("recordId",id);f.put("kind",chain);var ds=db.one("SELECT product_id FROM review_dataset WHERE id=:id",Map.of("id",f.get("datasetId")));f.put("productId",ds.get("productId"));Map<String,Object> current=source(chain,str(f,"currentSourceId"));Map<String,Object> audited=Objects.equals(f.get("currentSourceId"),f.get("auditedSourceId"))?current:source(chain,str(f,"auditedSourceId"));f.put("raw",current);f.put("auditedRaw",audited);String sourceBase=current!=null?(str(current,"baseRowId").isBlank()?str(current,"id"):str(current,"baseRowId")):audited!=null?(str(audited,"baseRowId").isBlank()?str(audited,"id"):str(audited,"baseRowId")):"";String findingBase=str(f,"baseFindingId").isBlank()?id:str(f,"baseFindingId");if(!str(f,"linkDetail").isBlank())f.put("linkDetail",db.decode(str(f,"linkDetail")));f.put("changes",db.rows("SELECT actor,action,reason,created_at,before_value,after_value FROM audit_event WHERE product_id=:p AND (target_id IN (SELECT id FROM "+Fields.sourceTable(chain)+" WHERE id=:sb OR base_row_id=:sb) OR target_id IN (SELECT id FROM risk_finding WHERE id=:fb OR base_finding_id=:fb)) ORDER BY created_at DESC LIMIT 30",map("p",ds.get("productId"),"sb",sourceBase,"fb",findingBase)));return f;
 }
 Map<String,Object> source(String chain,String id){return id.isBlank()?null:db.optional("SELECT * FROM "+Fields.sourceTable(chain)+" WHERE id=:id",Map.of("id",id));}
}
